/* Reset and base styles */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1a1e29;
  --meter-body: #4a5568;
  --meter-shadow: #2d3748;
  --meter-highlight: #718096;
  --screen-bg: #84cc16;
  --screen-text: #14532d;
  --screen-expired-bg: #ef4444;
  --screen-expired-text: #450a0a;
  --btn-bg: #cbd5e1;
  --btn-text: #0f172a;
  --btn-shadow: #64748b;
  --btn-danger-bg: #fca5a5;
  --btn-danger-text: #450a0a;
  --btn-danger-shadow: #b91c1c;
  --focus-ring: #38bdf8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  color: #fff;
}

.meter-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 360px;
}

.meter-cap {
  width: 140px;
  height: 24px;
  background: var(--meter-highlight);
  box-shadow: 0 -4px 0 0 var(--meter-shadow) inset;
  border-top-left-radius: 20px;
  border-top-right-radius: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.cap-light {
  width: 24px;
  height: 8px;
  background: #facc15;
  box-shadow: 0 0 8px #facc15;
}

.meter-housing {
  width: 100%;
  background-color: var(--meter-body);
  border: 6px solid var(--meter-shadow);
  box-shadow:
    inset 4px 4px 0 0 var(--meter-highlight),
    inset -4px -4px 0 0 var(--meter-shadow),
    0 12px 0 0 rgba(0, 0, 0, 0.4);
  border-radius: 8px;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.coin-slot-decoration {
  display: flex;
  justify-content: center;
}

.slot-line {
  width: 60px;
  height: 6px;
  background-color: #0f172a;
  border-bottom: 2px solid var(--meter-highlight);
}

.meter-screen {
  background-color: var(--screen-bg);
  color: var(--screen-text);
  border: 4px solid #0f172a;
  box-shadow: inset 3px 3px 0 0 rgba(0,0,0,0.3);
  padding: 16px;
  text-align: center;
  font-family: 'Courier New', monospace;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.meter-screen.expired {
  background-color: var(--screen-expired-bg);
  color: var(--screen-expired-text);
}

.screen-subhead {
  display: block;
  font-size: 0.85rem;
  letter-spacing: 2px;
  font-weight: bold;
  margin-bottom: 6px;
}

.screen-main-text {
  font-size: 2.25rem;
  font-weight: 900;
  letter-spacing: 2px;
  min-height: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.controls-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 800;
  color: var(--btn-text);
  background-color: var(--btn-bg);
  border: 3px solid #0f172a;
  box-shadow: 0 4px 0 0 var(--btn-shadow);
  padding: 14px 10px;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  outline: none;
  text-align: center;
}

.pixel-btn:hover {
  filter: brightness(1.08);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--focus-ring);
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 0 transparent;
}

.btn-danger {
  grid-column: span 2;
  background-color: var(--btn-danger-bg);
  color: var(--btn-danger-text);
  box-shadow: 0 4px 0 0 var(--btn-danger-shadow);
}

.meter-pole {
  width: 36px;
  height: 60px;
  background: #334155;
  border-left: 4px solid #475569;
  border-right: 4px solid #1e293b;
}

document.addEventListener('DOMContentLoaded', () => {
  let remainingSeconds = 0;
  let timerInterval = null;

  const screenEl = document.getElementById('meter-screen');
  const displayEl = document.getElementById('time-display');
  const btnAdd15 = document.getElementById('btn-add-15');
  const btnAdd60 = document.getElementById('btn-add-60');
  const btnReset = document.getElementById('btn-reset');

  function formatTime(totalSec) {
    const hours = Math.floor(totalSec / 3600);
    const minutes = Math.floor((totalSec % 3600) / 60);
    const seconds = totalSec % 60;
    const mm = String(minutes).padStart(2, '0');
    const ss = String(seconds).padStart(2, '0');
    return `${hours}:${mm}:${ss}`;
  }

  function render() {
    if (remainingSeconds <= 0) {
      remainingSeconds = 0;
      stopTimer();
      screenEl.classList.add('expired');
      displayEl.textContent = 'EXPIRED';
    } else {
      screenEl.classList.remove('expired');
      displayEl.textContent = formatTime(remainingSeconds);
    }
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      render();
    } else {
      stopTimer();
    }
  }

  function startTimer() {
    if (!timerInterval) {
      timerInterval = setInterval(tick, 1000);
    }
  }

  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function addMinutes(mins) {
    remainingSeconds += mins * 60;
    render();
    startTimer();
  }

  function reset() {
    remainingSeconds = 0;
    stopTimer();
    render();
  }

  btnAdd15.addEventListener('click', () => addMinutes(15));
  btnAdd60.addEventListener('click', () => addMinutes(60));
  btnReset.addEventListener('click', reset);

  render();
});
